-- SHALOM | Paso 2: Funciones publicas de catalogo y perfiles
-- Solo para Supabase de SHALOM (ehpvsasyzlrlypjjpzuk).
-- No ejecutar en el proyecto Juntos Hacia Dios.
-- No copia ni elimina cantos, artistas ni usuarios.
-- Si aparece un error, detente y comparte el mensaje antes de seguir.
BEGIN;
CREATE OR REPLACE FUNCTION public.get_artist_profile_summary(p_artist_id uuid)
 RETURNS TABLE(song_count bigint, collaboration_count bigint, album_count bigint, categories jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                                                                                                                                                                                                      with own_songs as (
                                                                                                                                                                                                                                                                                                                                                          select distinct sa.song_id
                                                                                                                                                                                                                                                                                                                                                              from public.song_artists sa
                                                                                                                                                                                                                                                                                                                                                                  where sa.artist_id = p_artist_id
                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                      category_counts as (
                                                                                                                                                                                                                                                                                                                                                                          select sc.category_id, count(distinct sc.song_id)::bigint as song_count
                                                                                                                                                                                                                                                                                                                                                                              from own_songs own
                                                                                                                                                                                                                                                                                                                                                                                  join public.song_categories sc on sc.song_id = own.song_id
                                                                                                                                                                                                                                                                                                                                                                                      group by sc.category_id
                                                                                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                                                                                          select
                                                                                                                                                                                                                                                                                                                                                                                              (select count(*)::bigint from own_songs) as song_count,
                                                                                                                                                                                                                                                                                                                                                                                                  (select count(*)::bigint from own_songs own where exists (
                                                                                                                                                                                                                                                                                                                                                                                                        select 1 from public.song_artists other
                                                                                                                                                                                                                                                                                                                                                                                                              where other.song_id = own.song_id and other.artist_id <> p_artist_id
                                                                                                                                                                                                                                                                                                                                                                                                                  )) as collaboration_count,
                                                                                                                                                                                                                                                                                                                                                                                                                      (select count(*)::bigint from public.albums al where al.artist_id = p_artist_id) as album_count,
                                                                                                                                                                                                                                                                                                                                                                                                                          coalesce((
                                                                                                                                                                                                                                                                                                                                                                                                                                select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'slug', c.slug, 'song_count', cc.song_count) order by cc.song_count desc, lower(c.name))
                                                                                                                                                                                                                                                                                                                                                                                                                                      from category_counts cc
                                                                                                                                                                                                                                                                                                                                                                                                                                            join public.categories c on c.id = cc.category_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                ), '[]'::jsonb) as categories;
                                                                                                                                                                                                                                                                                                                                                                                                                                                $function$;
REVOKE EXECUTE ON FUNCTION public.get_artist_profile_summary(p_artist_id uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_artist_profile_summary(p_artist_id uuid) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.get_categories_catalog()
 RETURNS TABLE(id uuid, name text, slug text, parent_id uuid, song_type text, description text, sort_order integer, song_count bigint, child_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
                                                                                                                                                                                                                                                                                      with recursive category_tree(root_id, descendant_id, path) as (
                                                                                                                                                                                                                                                                                          select
                                                                                                                                                                                                                                                                                                c.id,
                                                                                                                                                                                                                                                                                                      c.id,
                                                                                                                                                                                                                                                                                                            array[c.id]
                                                                                                                                                                                                                                                                                                                from public.categories c

                                                                                                                                                                                                                                                                                                                    union all

                                                                                                                                                                                                                                                                                                                        select
                                                                                                                                                                                                                                                                                                                              tree.root_id,
                                                                                                                                                                                                                                                                                                                                    child.id,
                                                                                                                                                                                                                                                                                                                                          tree.path || child.id
                                                                                                                                                                                                                                                                                                                                              from category_tree tree
                                                                                                                                                                                                                                                                                                                                                  join public.categories child
                                                                                                                                                                                                                                                                                                                                                        on child.parent_id = tree.descendant_id
                                                                                                                                                                                                                                                                                                                                                            where not child.id = any(tree.path)
                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                song_counts as (
                                                                                                                                                                                                                                                                                                                                                                    select
                                                                                                                                                                                                                                                                                                                                                                          tree.root_id,
                                                                                                                                                                                                                                                                                                                                                                                count(distinct sc.song_id)::bigint as song_count
                                                                                                                                                                                                                                                                                                                                                                                    from category_tree tree
                                                                                                                                                                                                                                                                                                                                                                                        left join public.song_categories sc
                                                                                                                                                                                                                                                                                                                                                                                              on sc.category_id = tree.descendant_id
                                                                                                                                                                                                                                                                                                                                                                                                  group by tree.root_id
                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                      child_counts as (
                                                                                                                                                                                                                                                                                                                                                                                                          select
                                                                                                                                                                                                                                                                                                                                                                                                                parent_id,
                                                                                                                                                                                                                                                                                                                                                                                                                      count(*)::bigint as child_count
                                                                                                                                                                                                                                                                                                                                                                                                                          from public.categories
                                                                                                                                                                                                                                                                                                                                                                                                                              where parent_id is not null
                                                                                                                                                                                                                                                                                                                                                                                                                                  group by parent_id
                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                      select
                                                                                                                                                                                                                                                                                                                                                                                                                                          c.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                              coalesce(c.name, '')::text as name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                  coalesce(c.slug, '')::text as slug,
                                                                                                                                                                                                                                                                                                                                                                                                                                                      c.parent_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                          coalesce(c.song_type, '')::text as song_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                              coalesce(to_jsonb(c) ->> 'description', '')::text as description,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  coalesce(c.sort_order, 0)::integer as sort_order,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      coalesce(sc.song_count, 0)::bigint as song_count,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          coalesce(cc.child_count, 0)::bigint as child_count
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            from public.categories c
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              left join song_counts sc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  on sc.root_id = c.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    left join child_counts cc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        on cc.parent_id = c.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          order by
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              coalesce(c.sort_order, 0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  lower(c.name),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      c.id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $function$;
REVOKE EXECUTE ON FUNCTION public.get_categories_catalog() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_categories_catalog() TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.search_albums_catalog(p_query text DEFAULT NULL::text, p_artist_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 24, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, title text, slug text, description text, year text, artist_id uuid, artist_name text, song_count bigint, total_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
                                  with filtered as (
                                      select
                                            al.id,
                                                  coalesce(al.title, '')::text as title,
                                                        coalesce(al.slug, '')::text as slug,
                                                              coalesce(to_jsonb(al) ->> 'description', '')::text as description,
                                                                    coalesce(to_jsonb(al) ->> 'year', '')::text as year,
                                                                          al.artist_id,
                                                                                coalesce(ar.name, '')::text as artist_name,
                                                                                      count(distinct als.song_id)::bigint as song_count
                                                                                          from public.albums al
                                                                                              left join public.artists ar
                                                                                                    on ar.id = al.artist_id
                                                                                                        left join public.album_songs als
                                                                                                              on als.album_id = al.id
                                                                                                                  where
                                                                                                                        (p_artist_id is null or al.artist_id = p_artist_id)
                                                                                                                              and (
                                                                                                                                      nullif(btrim(coalesce(p_query, '')), '') is null
                                                                                                                                              or concat_ws(
                                                                                                                                                        ' ',
                                                                                                                                                                  al.title,
                                                                                                                                                                            to_jsonb(al) ->> 'description',
                                                                                                                                                                                      to_jsonb(al) ->> 'year',
                                                                                                                                                                                                ar.name
                                                                                                                                                                                                        ) ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                              )
                                                                                                                                                                                                                  group by al.id, ar.id
                                                                                                                                                                                                                    )
                                                                                                                                                                                                                      select
                                                                                                                                                                                                                          f.id,
                                                                                                                                                                                                                              f.title,
                                                                                                                                                                                                                                  f.slug,
                                                                                                                                                                                                                                      f.description,
                                                                                                                                                                                                                                          f.year,
                                                                                                                                                                                                                                              f.artist_id,
                                                                                                                                                                                                                                                  f.artist_name,
                                                                                                                                                                                                                                                      f.song_count,
                                                                                                                                                                                                                                                          count(*) over () as total_count
                                                                                                                                                                                                                                                            from filtered f
                                                                                                                                                                                                                                                              order by lower(f.title), f.id
                                                                                                                                                                                                                                                                limit least(greatest(coalesce(p_limit, 24), 1), 100)
                                                                                                                                                                                                                                                                  offset greatest(coalesce(p_offset, 0), 0);
                                                                                                                                                                                                                                                                  $function$;
REVOKE EXECUTE ON FUNCTION public.search_albums_catalog(p_query text, p_artist_id uuid, p_limit integer, p_offset integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.search_albums_catalog(p_query text, p_artist_id uuid, p_limit integer, p_offset integer) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.search_artist_songs_catalog(p_artist_id uuid, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 24, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, title text, slug text, tone text, song_type text, difficulty text, artists jsonb, categories jsonb, albums jsonb, total_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
                                with filtered as (
                                    select
                                          s.id,
                                                s.title,
                                                      s.slug,
                                                            s.tone,
                                                                  s.song_type,
                                                                        s.difficulty,
                                                                              coalesce((
                                                                                      select jsonb_agg(jsonb_build_object('id', a.id, 'name', a.name, 'artist_type', to_jsonb(a) ->> 'artist_type') order by lower(a.name))
                                                                                              from public.song_artists sa
                                                                                                      join public.artists a on a.id = sa.artist_id
                                                                                                              where sa.song_id = s.id
                                                                                                                    ), '[]'::jsonb) as artists,
                                                                                                                          coalesce((
                                                                                                                                  select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'slug', c.slug) order by lower(c.name))
                                                                                                                                          from public.song_categories sc
                                                                                                                                                  join public.categories c on c.id = sc.category_id
                                                                                                                                                          where sc.song_id = s.id
                                                                                                                                                                ), '[]'::jsonb) as categories,
                                                                                                                                                                      coalesce((
                                                                                                                                                                              select jsonb_agg(jsonb_build_object('id', al.id, 'title', al.title, 'slug', al.slug) order by lower(al.title))
                                                                                                                                                                                      from public.album_songs als
                                                                                                                                                                                              join public.albums al on al.id = als.album_id
                                                                                                                                                                                                      where als.song_id = s.id
                                                                                                                                                                                                            ), '[]'::jsonb) as albums
                                                                                                                                                                                                                from public.songs s
                                                                                                                                                                                                                    where exists (
                                                                                                                                                                                                                          select 1 from public.song_artists own
                                                                                                                                                                                                                                where own.song_id = s.id and own.artist_id = p_artist_id
                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                        and (
                                                                                                                                                                                                                                              nullif(btrim(coalesce(p_query, '')), '') is null
                                                                                                                                                                                                                                                    or coalesce(s.title, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                          or coalesce(s.tone, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                or coalesce(s.difficulty, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                      or coalesce(s.song_type, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                            or exists (
                                                                                                                                                                                                                                                                                    select 1
                                                                                                                                                                                                                                                                                            from public.song_categories sc
                                                                                                                                                                                                                                                                                                    join public.categories c on c.id = sc.category_id
                                                                                                                                                                                                                                                                                                            where sc.song_id = s.id
                                                                                                                                                                                                                                                                                                                      and coalesce(c.name, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                    select f.id, f.title, f.slug, f.tone, f.song_type, f.difficulty, f.artists, f.categories, f.albums, count(*) over () as total_count
                                                                                                                                                                                                                                                                                                                                      from filtered f
                                                                                                                                                                                                                                                                                                                                        order by lower(f.title), f.id
                                                                                                                                                                                                                                                                                                                                          limit least(greatest(coalesce(p_limit, 24), 1), 100)
                                                                                                                                                                                                                                                                                                                                            offset greatest(coalesce(p_offset, 0), 0);
                                                                                                                                                                                                                                                                                                                                            $function$;
REVOKE EXECUTE ON FUNCTION public.search_artist_songs_catalog(p_artist_id uuid, p_query text, p_limit integer, p_offset integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.search_artist_songs_catalog(p_artist_id uuid, p_query text, p_limit integer, p_offset integer) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.search_artists_catalog(p_query text DEFAULT NULL::text, p_artist_type text DEFAULT NULL::text, p_limit integer DEFAULT 24, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, name text, slug text, artist_type text, bio text, description text, song_count bigint, total_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
                              with filtered as (
                                  select
                                        a.id,
                                              coalesce(a.name, '')::text as name,
                                                    coalesce(a.slug, '')::text as slug,
                                                          coalesce(
                                                                  to_jsonb(a) ->> 'artist_type',
                                                                          to_jsonb(a) ->> 'type',
                                                                                  ''
                                                                                        )::text as artist_type,
                                                                                              coalesce(to_jsonb(a) ->> 'bio', '')::text as bio,
                                                                                                    coalesce(to_jsonb(a) ->> 'description', '')::text as description,
                                                                                                          count(distinct sa.song_id)::bigint as song_count
                                                                                                              from public.artists a
                                                                                                                  left join public.song_artists sa
                                                                                                                        on sa.artist_id = a.id
                                                                                                                            where
                                                                                                                                  (
                                                                                                                                          nullif(btrim(coalesce(p_artist_type, '')), '') is null
                                                                                                                                                  or translate(
                                                                                                                                                            lower(
                                                                                                                                                                        coalesce(
                                                                                                                                                                                      to_jsonb(a) ->> 'artist_type',
                                                                                                                                                                                                    to_jsonb(a) ->> 'type',
                                                                                                                                                                                                                  ''
                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                  'áéíóúü',
                                                                                                                                                                                                                                                            'aeiouu'
                                                                                                                                                                                                                                                                    ) like '%' || translate(
                                                                                                                                                                                                                                                                              lower(btrim(p_artist_type)),
                                                                                                                                                                                                                                                                                        'áéíóúü',
                                                                                                                                                                                                                                                                                                  'aeiouu'
                                                                                                                                                                                                                                                                                                          ) || '%'
                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                      and (
                                                                                                                                                                                                                                                                                                                              nullif(btrim(coalesce(p_query, '')), '') is null
                                                                                                                                                                                                                                                                                                                                      or concat_ws(
                                                                                                                                                                                                                                                                                                                                                ' ',
                                                                                                                                                                                                                                                                                                                                                          a.name,
                                                                                                                                                                                                                                                                                                                                                                    to_jsonb(a) ->> 'bio',
                                                                                                                                                                                                                                                                                                                                                                              to_jsonb(a) ->> 'description',
                                                                                                                                                                                                                                                                                                                                                                                        to_jsonb(a) ->> 'artist_type',
                                                                                                                                                                                                                                                                                                                                                                                                  to_jsonb(a) ->> 'type'
                                                                                                                                                                                                                                                                                                                                                                                                          ) ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                    group by a.id
                                                                                                                                                                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                                                                                                                                                        select
                                                                                                                                                                                                                                                                                                                                                                                                                            f.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                f.name,
                                                                                                                                                                                                                                                                                                                                                                                                                                    f.slug,
                                                                                                                                                                                                                                                                                                                                                                                                                                        f.artist_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                            f.bio,
                                                                                                                                                                                                                                                                                                                                                                                                                                                f.description,
                                                                                                                                                                                                                                                                                                                                                                                                                                                    f.song_count,
                                                                                                                                                                                                                                                                                                                                                                                                                                                        count(*) over () as total_count
                                                                                                                                                                                                                                                                                                                                                                                                                                                          from filtered f
                                                                                                                                                                                                                                                                                                                                                                                                                                                            order by lower(f.name), f.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                              limit least(greatest(coalesce(p_limit, 24), 1), 100)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                offset greatest(coalesce(p_offset, 0), 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                $function$;
REVOKE EXECUTE ON FUNCTION public.search_artists_catalog(p_query text, p_artist_type text, p_limit integer, p_offset integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.search_artists_catalog(p_query text, p_artist_type text, p_limit integer, p_offset integer) TO anon, authenticated;
COMMIT;
